    "starter": "def can_cross(grid: list[list[int]], t: int) -> bool:\n    # Your code here\n    pass\n",
    "solution": "def can_cross(grid, t):\n    n = len(grid)\n    if grid[0][0] > t:\n        return False\n    seen = {(0, 0)}\n    stack = [(0, 0)]\n    while stack:\n        r, c = stack.pop()\n        for i, j in ((r + 1, c), (r - 1, c), (r, c + 1), (r, c - 1)):\n            if 0 <= i < n and 0 <= j < n and (i, j) not in seen and grid[i][j] <= t:\n                seen.add((i, j)); stack.append((i, j))\n    return (n - 1, n - 1) in seen\n",
